## testing seurat's bestimport pandas as pdimport numpy as npfrom sklearn.metrics import mutual_info_scorefrom collections import Counterfrom tqdm import tqdmfrom scipy.io import mmread expression_matrix = mmread("/Users/ggraham/MERFISH/2025_10_06_genes_meeting_criteria.mtx")""" here, rows are genes (unlabeled) and columns are cells,all of the genes listed here are marker genes that fit Duncans criteriato save computation"""expression_matrix = pd.DataFrame(expression_matrix.toarray())"convert to a dataframe"genes = pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_sparse_mat_rownames.csv")genes = genes['x']"""genes corresponds to the genes (rows) in expression matrix"""clusters = pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_clusters.csv")"""clusters['clusters'] corresponds to the cluster label for each cell"""# Set up data structure like the originalexpression_matrix.index = genes  # Set gene names as index# Create labels dataframe - make sure cell names match expression matrix columnscell_names = expression_matrix.columns df_labels = pd.DataFrame({    'label': clusters['clusters'].values,    'cell_label': cell_names}, index=cell_names)#read in seurat marker genesjoined_markers_pval =  pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_joined_markers_pval.csv")joined_markers_log2fc =pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_joined_markers_log2fc.csv")pval_genes = joined_markers_pval['gene']log2fc_genes = joined_markers_log2fc['gene']## machine learning time babeyfrom sklearn.model_selection import cross_val_score, StratifiedKFoldfrom sklearn.ensemble import RandomForestClassifierfrom sklearn.metrics import accuracy_scoreimport numpy as np    #pval # Prepare data - transpose so cells are rows, genes are columnspval_X = expression_matrix.loc[pval_genes].Tpval_y = df_labels['label']# Initialize classifierpval_clf = RandomForestClassifier(n_estimators=100, random_state=42)# Perform cross-validationpval_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)pval_cv_scores = cross_val_score(pval_clf, pval_X, pval_y, cv=pval_cv, scoring='accuracy')# Calculate metricspval_mean_accuracy = np.mean(pval_cv_scores) # 43%pval_std_accuracy = np.std(pval_cv_scores)#log2fc# Prepare data - transpose so cells are rows, genes are columnslog2fc_X = expression_matrix.loc[log2fc_genes].Tlog2fc_y = df_labels['label']# Initialize classifierlog2fc_clf = RandomForestClassifier(n_estimators=100, random_state=42)# Perform cross-validationlog2fc_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)log2fc_cv_scores = cross_val_score(log2fc_clf, log2fc_X, log2fc_y, cv=log2fc_cv, scoring='accuracy')# Calculate metricslog2fc_mean_accuracy = np.mean(log2fc_cv_scores) log2fc__std_accuracy = np.std(log2fc_cv_scores)print(pval_mean_accuracy)print(log2fc_mean_accuracy)print(log2fc_genes.isin( pval_genes))#try with just random fucking genesimport randomrandom_genes = random.sample(sorted(genes),  105)# Prepare data - transpose so cells are rows, genes are columnsrandom_X = expression_matrix.loc[random_genes].Trandom_y = df_labels['label']# Initialize classifierrandom_clf = RandomForestClassifier(n_estimators=100, random_state=42)# Perform cross-validationrandom_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)random_cv_scores = cross_val_score(random_clf, random_X, random_y, cv=random_cv, scoring='accuracy')# Calculate metricsrandom_mean_accuracy = np.mean(random_cv_scores)# 36%random_std_accuracy = np.std(random_cv_scores)